const e="n3-test-4",t="N3",n="JLPT N3 Practice Test 4",o={vocabulary:{timeLimit:30,questions:[{id:"v1",type:"kanji-reading",question:"社長に【報告】する。",options:["ほうこく","ぼうこく","ほうごく","ぼうごく"],correctAnswer:0,explanation:"報告 (ほうこく) means 'report'."},{id:"v2",type:"kanji-reading",question:"【商品】の値段を確認する。",options:["しょうひん","しょうびん","じょうひん","じょうびん"],correctAnswer:0,explanation:"商品 (しょうひん) means 'product / goods'."},{id:"v3",type:"kanji-reading",question:"彼は【正直】な人だ。",options:["しょうじき","しょうしょく","せいじき","せいしょく"],correctAnswer:0,explanation:"正直 (しょうじき) means 'honest'."},{id:"v4",type:"kanji-reading",question:"新しい【技術】を開発する。",options:["ぎじゅつ","ぎじつ","きじゅつ","きじつ"],correctAnswer:0,explanation:"技術 (ぎじゅつ) means 'technology / skill'."},{id:"v5",type:"kanji-reading",question:"【規則】を守るべきだ。",options:["きそく","きほう","きじゅん","きかく"],correctAnswer:0,explanation:"規則 (きそく) means 'rule / regulation'."},{id:"v6",type:"kanji-reading",question:"この国は【平和】だ。",options:["へいわ","へいか","ひょうわ","ひょうか"],correctAnswer:0,explanation:"平和 (へいわ) means 'peace'."},{id:"v7",type:"kanji-reading",question:"日本の【文化】について学ぶ。",options:["ぶんか","ぶんが","もんか","もんが"],correctAnswer:0,explanation:"文化 (ぶんか) means 'culture'."},{id:"v8",type:"kanji-reading",question:"彼の【態度】は丁寧だ。",options:["たいど","たいと","だいど","だいと"],correctAnswer:0,explanation:"態度 (たいど) means 'attitude'."},{id:"v9",type:"orthography",question:"【きぼう】の職種に就く。",options:["希望","期望","気望","祈望"],correctAnswer:0,explanation:"希望 (きぼう) is the kanji for hope/wish."},{id:"v10",type:"orthography",question:"仕事の【けいけん】を生かす。",options:["経験","経済","経検","刑験"],correctAnswer:0,explanation:"経験 (けいけん) is the kanji for experience."},{id:"v11",type:"orthography",question:"【さんか】費を払う。",options:["参加","賛加","参過","賛過"],correctAnswer:0,explanation:"参加 (さんか) is the kanji for participation."},{id:"v12",type:"orthography",question:"【りゆう】を説明する。",options:["理由","理有","利由","里由"],correctAnswer:0,explanation:"理由 (りゆう) is the kanji for reason."},{id:"v13",type:"orthography",question:"【きかい】があれば行く。",options:["機会","機械","器械","期会"],correctAnswer:0,explanation:"機会 (きかい) is the kanji for opportunity/chance."},{id:"v14",type:"orthography",question:"【じゅんび】が整った。",options:["準備","準美","順備","順美"],correctAnswer:0,explanation:"準備 (じゅんび) is the kanji for preparation."},{id:"v15",type:"context",question:"彼は（　　）が広いので、多くの人に知られている。",options:["顔","口","耳","目"],correctAnswer:0,explanation:"顔が広い (かおがひろい) means 'to have a wide circle of acquaintances'."},{id:"v16",type:"context",question:"今日は（　　）が悪いので、お腹が痛い。",options:["きぶん","ぐあい","つごう","きげん"],correctAnswer:1,explanation:"具合 (ぐあい) is used for physical condition."},{id:"v17",type:"context",question:"この靴は私に（　　）だ。",options:["ぴったり","すっきり","さっぱり","しっかり"],correctAnswer:0,explanation:"ぴったり means 'perfect fit'."},{id:"v18",type:"context",question:"彼はいつも（　　）遅刻してくる。",options:["わざと","きっと","ずっと","やっと"],correctAnswer:0,explanation:"わざと means 'on purpose'."},{id:"v19",type:"context",question:"明日の（　　）を確認する。",options:["よてい","やくそく","けいかく","ようじ"],correctAnswer:0,explanation:"予定 (よてい) means 'schedule/plan'."},{id:"v20",type:"context",question:"（　　）、彼が言ったことは本当だった。",options:["たしかに","すっかり","うっかり","がっかり"],correctAnswer:0,explanation:"確かに (たしかに) means 'surely / indeed'."},{id:"v21",type:"context",question:"彼女はとても（　　）なので、みんなに好かれている。",options:["しんせつ","ていねい","まじめ","きびしい"],correctAnswer:0,explanation:"親切 (しんせつ) means 'kind'."},{id:"v22",type:"context",question:"テストの前に（　　）をしておく。",options:["ふくしゅう","よしゅう","しゅくだい","れんしゅう"],correctAnswer:0,explanation:"復習 (ふくしゅう) means 'review'."},{id:"v23",type:"context",question:"このカメラは（　　）が良い。",options:["せいのお","せいかく","せいしつ","せいのう"],correctAnswer:3,explanation:"性能 (せいのう) means 'performance/specifications'."},{id:"v24",type:"context",question:"今日は（　　）が多いので、道が混んでいる。",options:["こうつうりょう","ひとで","くるま","じてんしゃ"],correctAnswer:0,explanation:"交通量 (こうつうりょう) means 'traffic volume'."},{id:"v25",type:"context",question:"彼は（　　）を立てて計画を進めた。",options:["すじみち","けいかく","もくひょう","よてい"],correctAnswer:0,explanation:"筋道 (すじみち) を立てる means 'to make a logical plan/path'."},{id:"v26",type:"paraphrase",question:"彼は【器用】だ。",options:["彼は手先が上手だ。","彼は頭がいい。","彼は足が速い。","彼は力が強い。"],correctAnswer:0,explanation:"器用 (きよう) means skillful, especially with one's hands (手先が上手だ)."},{id:"v27",type:"paraphrase",question:"【とっくに】終わりました。",options:["ずっと前に終わりました。","今終わりました。","これから終わります。","もうすぐ終わります。"],correctAnswer:0,explanation:"とっくに means long ago / already (ずっと前に)."},{id:"v28",type:"paraphrase",question:"この仕事は【きつい】。",options:["この仕事は大変だ。","この仕事は簡単だ。","この仕事は面白い。","この仕事は退屈だ。"],correctAnswer:0,explanation:"きつい means tough or hard (大変だ)."},{id:"v29",type:"paraphrase",question:"【なるべく】早く来てください。",options:["できるだけ早く来てください。","絶対に早く来てください。","無理しないで早く来てください。","必ず早く来てください。"],correctAnswer:0,explanation:"なるべく means as much as possible (できるだけ)."},{id:"v30",type:"paraphrase",question:"彼は【慌てて】出て行った。",options:["彼は急いで出て行った。","彼は怒って出て行った。","彼は泣きながら出て行った。","彼は静かに出て行った。"],correctAnswer:0,explanation:"慌てる means to panic/hurry (急いで)."},{id:"v31",type:"paraphrase",question:"この服は【地味だ】。",options:["この服は色が暗くて目立たない。","この服は色が明るくて目立つ。","この服は高くて買えない。","この服は安くて粗悪だ。"],correctAnswer:0,explanation:"地味 (じみ) means plain (色が暗くて目立たない)."},{id:"v32",type:"paraphrase",question:"【ついに】完成した。",options:["やっと完成した。","すぐに完成した。","これから完成する。","まだ完成していない。"],correctAnswer:0,explanation:"ついに means finally / at last (やっと)."},{id:"v33",type:"paraphrase",question:"彼は【素直】だ。",options:["彼は人の言うことをよく聞く。","彼は嘘ばかりつく。","彼は怒りっぽい。","彼は静かだ。"],correctAnswer:0,explanation:"素直 (すなお) means obedient/honest (人の言うことをよく聞く)."},{id:"v34",type:"paraphrase",question:"部屋が【片付いた】。",options:["部屋がきれいになった。","部屋が汚くなった。","部屋が広くなった。","部屋が狭くなった。"],correctAnswer:0,explanation:"片付く means to be put in order (きれいになった)."},{id:"v35",type:"paraphrase",question:"【おそらく】雨だろう。",options:["たぶん雨だろう。","絶対に雨だろう。","少し雨だろう。","ずっと雨だろう。"],correctAnswer:0,explanation:"おそらく means probably (たぶん)."}]},grammar:{timeLimit:30,questions:[{id:"g1",type:"grammar-fill",question:"彼が来ない（　　）、何か理由があるはずだ。",options:["からには","ことには","ためには","わけには"],correctAnswer:0,explanation:"〜からには (now that / since)."},{id:"g2",type:"grammar-fill",question:"このレストランは美味しい（　　）、いつも混んでいる。",options:["だけに","ばかりか","うえに","だけでなく"],correctAnswer:0,explanation:"〜だけに (precisely because)."},{id:"g3",type:"grammar-fill",question:"明日の会議は、社長（　　）中止になりました。",options:["によって","について","に対して","にとって"],correctAnswer:0,explanation:"〜によって (by) indicates the agent of an action."},{id:"g4",type:"grammar-fill",question:"あの人は毎日運動しているから、病気になる（　　）。",options:["はずがない","わけにはいかない","ことになっている","ものだ"],correctAnswer:0,explanation:"〜はずがない (it's impossible that / there's no way)."},{id:"g5",type:"grammar-fill",question:"このパソコンは古い（　　）、とても使いやすい。",options:["わりに","くせに","せいで","おかげで"],correctAnswer:0,explanation:"〜わりに (for / considering that)."},{id:"g6",type:"grammar-fill",question:"彼はまるで日本人（　　）日本語を話す。",options:["のように","みたいに","らしく","そうで"],correctAnswer:0,explanation:"まるで〜のように (just like)."},{id:"g7",type:"grammar-fill",question:"明日は早く起きる（　　）、もう寝ます。",options:["から","ので","ため","ことだから"],correctAnswer:0,explanation:"〜から (because) is used before expressions of volition."},{id:"g8",type:"grammar-fill",question:"私が言った（　　）書いてください。",options:["とおりに","ままに","ように","ために"],correctAnswer:0,explanation:"〜とおりに (exactly as)."},{id:"g9",type:"grammar-fill",question:"田中さんは今、出かけている（　　）です。",options:["最中","間","うち","たび"],correctAnswer:0,explanation:"〜最中だ (in the middle of doing)."},{id:"g10",type:"grammar-fill",question:"いくら練習し（　　）、上手になりません。",options:["ても","たら","れば","と"],correctAnswer:0,explanation:"いくら〜ても (no matter how much)."},{id:"g11",type:"grammar-fill",question:"私（　　）、家族が一番大切です。",options:["にとって","について","に対して","によって"],correctAnswer:0,explanation:"〜にとって (for / from the perspective of)."},{id:"g12",type:"grammar-fill",question:"明日は早く起きなければならないから、もう寝る（　　）。",options:["ことにする","ことになる","ようにする","ようになる"],correctAnswer:0,explanation:"〜ことにする (I decide to do)."},{id:"g13",type:"grammar-fill",question:"雨が降っているから、今日は出かけない（　　）。",options:["でおこう","てしまおう","てみよう","てこよう"],correctAnswer:0,explanation:"〜ておく / 〜でおく (to leave it as it is). 出かけないでおく (leave it as not going out)."},{id:"g14",type:"grammar-fill",question:`次の文の ★ に入る最もよいものを一つ選びなさい。
こんな ___ ___ ★ ___ とは ___ 思わなかった。`,options:["難しい","こと","になる","大変な"],correctAnswer:2,explanation:"The correct order is: こんな大変なことになるとは思わなかった。 The star is 'になる'."},{id:"g15",type:"grammar-fill",question:"この ___ ___ ★ ___ に ___ させてください。",options:["仕事","は","ぜひ","私"],correctAnswer:2,explanation:"The correct order is: この仕事はぜひ私にさせてください。 The star is 'ぜひ'."},{id:"g16",type:"grammar-fill",question:"あの ___ ___ ★ ___ は ___ になっています。",options:["若者","の","間","で"],correctAnswer:2,explanation:"The correct order is: あの映画は若者の間で人気になっています。 The star is '間'."},{id:"g17",type:"grammar-fill",question:"彼 ___ ___ ★ ___ を ___ があります。",options:["は","その本","読んだ","こと"],correctAnswer:3,explanation:"The correct order is: 彼はその本を読んだことがあります。 The star is 'こと'."},{id:"g18",type:"grammar-fill",question:"明日 ___ ___ ★ ___ 遊びに ___ ください。",options:["暇","なら","ぜひ","うちへ"],correctAnswer:3,explanation:"The correct order is: 明日暇ならぜひうちへ遊びに来てください。 The star is 'うちへ'."}]},reading:{timeLimit:40,passages:[{id:"p1",text:"日本の駅や街角には、飲み物の自動販売機がたくさんあります。自動販売機は24時間いつでも冷たい飲み物や温かい飲み物を買うことができて、とても便利です。しかし、電気をたくさん使うという問題もあります。最近では、電気をあまり使わない省エネの自動販売機も増えてきています。",questions:[{id:"r1",type:"reading-comprehension",question:"自動販売機の長所は何ですか。",options:["24時間いつでも飲み物が買えること","電気をたくさん使うこと","お金を節約できること","いろいろな種類があること"],correctAnswer:0,explanation:"The text says '24時間いつでも冷たい飲み物や温かい飲み物を買うことができて、とても便利です'."},{id:"r2",type:"reading-comprehension",question:"自動販売機の短所は何ですか。",options:["電気をたくさん使うこと","飲み物が少ないこと","壊れやすいこと","見つけにくいこと"],correctAnswer:0,explanation:"The text says 'しかし、電気をたくさん使うという問題もあります'."}]},{id:"p2",text:"私は先週末、一人で温泉に行きました。温泉に入ると、体の疲れが取れて、とてもリラックスできます。また、温泉の周りの景色もきれいで、心が落ち着きました。しかし、温泉の温度が高すぎて、長く入っていられなかったのが少し残念でした。次回は、もう少し温度の低い温泉に行きたいです。",questions:[{id:"r3",type:"reading-comprehension",question:"温泉に入ってどう感じましたか。",options:["体の疲れが取れてリラックスできた","疲れがもっとひどくなった","退屈だった","景色がきれいではなかった"],correctAnswer:0,explanation:"The text says '体の疲れが取れて、とてもリラックスできます'."},{id:"r4",type:"reading-comprehension",question:"何が少し残念でしたか。",options:["温泉の温度が高すぎたこと","景色がきれいでなかったこと","お金がかかりすぎたこと","一人だったこと"],correctAnswer:0,explanation:"The text says '温泉の温度が高すぎて、長く入っていられなかったのが少し残念でした'."}]},{id:"p3",text:`【町内会の皆様へ ゴミの出し方について】
・燃えるゴミは、毎週火曜日と金曜日の朝8時までに出してください。
・燃えないゴミは、第1・第3水曜日の朝8時までに出してください。
・粗大ゴミ（自転車、家具など）は、市役所に連絡して回収日を決めてください。有料です。
・ゴミは決められた場所に置いてください。他の場所に置くと、近所の迷惑になります。`,questions:[{id:"r5",type:"reading-comprehension",question:"燃えるゴミはいつ出しますか。",options:["毎週火曜日と金曜日の朝8時まで","毎週水曜日の朝8時まで","第1・第3水曜日の朝8時まで","いつでもいい"],correctAnswer:0,explanation:"The text says '燃えるゴミは、毎週火曜日と金曜日の朝8時までに出してください'."},{id:"r6",type:"reading-comprehension",question:"古い自転車を捨てたい時、どうすればいいですか。",options:["火曜日の朝にゴミ置き場に出す","市役所に連絡して回収日を決める","燃えないゴミの日に出す","どこかに置いておく"],correctAnswer:1,explanation:"The text says '粗大ゴミ（自転車、家具など）は、市役所に連絡して回収日を決めてください'."},{id:"r7",type:"reading-comprehension",question:"ゴミの出し方について、注意することは何ですか。",options:["決められた場所に置くこと","夜に出すこと","きれいに洗って出すこと","できるだけ少なくすること"],correctAnswer:0,explanation:"The text says 'ゴミは決められた場所に置いてください'."}]}]}},i={id:e,level:t,title:n,sections:o};export{i as default,e as id,t as level,o as sections,n as title};
